"use client";
import React, { useEffect, useState } from 'react';
import Link from 'next/link';
import { motion, AnimatePresence } from 'framer-motion';
import { ArrowUpRight, Feather, Search, Heart, Share2, Sparkles, BookOpen } from 'lucide-react';
import { db } from '@/firebase';
import { collection, getDocs, query, orderBy, where } from 'firebase/firestore';

export default function PoetryPage() {
  const [poems, setPoems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [activeType, setActiveType] = useState('All');

  useEffect(() => {
    // Basic SEO meta tags injection
    document.title = 'Poetry | Suleman Zaheer | Dark Luxury Words';
    let metaDesc = document.querySelector('meta[name="description"]');
    if (!metaDesc) {
      metaDesc = document.createElement('meta');
      metaDesc.name = 'description';
      document.head.appendChild(metaDesc);
    }
    metaDesc.content = 'Explore an exclusive collection of deep and soulful poetry, Ghazals, and Nazms written by Suleman Zaheer.';

    const fetchPoems = async () => {
      try {
        const q = query(
          collection(db, 'poems'), 
          where('published', '==', true),
          orderBy('publishedAt', 'desc')
        );
        const snapshot = await getDocs(q);
        setPoems(snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() })));
      } catch (error) {
        console.error("Error fetching poems:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchPoems();
  }, []);

  const generateSchema = () => {
    return {
      '@context': 'https://schema.org',
      '@type': 'CollectionPage',
      name: 'Poetry Collection - Suleman Zaheer',
      description: 'A premium collection of Urdu and English poetry, Ghazals, and Nazms by Suleman Zaheer.',
      url: 'https://suleman-zaheer.web.app/poetry',
      hasPart: poems.map(poem => ({
        '@type': 'CreativeWork',
        headline: poem.title,
        genre: poem.type,
        inLanguage: poem.language,
        author: {
          '@type': 'Person',
          name: 'Suleman Zaheer',
        },
        url: `https://suleman-zaheer.web.app/poetry/${poem.slug}`,
      }))
    };
  };

  const filteredPoems = poems.filter(poem => {
    const matchesSearch = poem.title.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          (poem.content && poem.content.toLowerCase().includes(searchTerm.toLowerCase())) ||
                          (poem.themes && poem.themes.some(t => t.toLowerCase().includes(searchTerm.toLowerCase())));
    const matchesType = activeType === 'All' || poem.type === activeType;
    return matchesSearch && matchesType;
  });

  const uniqueTypes = ['All', ...new Set(poems.map(p => p.type).filter(Boolean))];

  return (
    <main className="min-h-screen bg-neutral-950 text-white font-sans selection:bg-primary/30 relative overflow-hidden">
      {!loading && poems.length > 0 && (
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{ __html: JSON.stringify(generateSchema()) }}
        />
      )}

      {/* Luxury Background Elements */}
      <div className="absolute top-[-10%] left-[-10%] w-[50%] h-[50%] bg-gradient-to-br from-primary/10 to-transparent blur-[120px] rounded-full pointer-events-none mix-blend-screen" />
      <div className="absolute bottom-[-10%] right-[-10%] w-[60%] h-[60%] bg-gradient-to-tl from-rose-900/10 to-transparent blur-[150px] rounded-full pointer-events-none mix-blend-screen" />

      <div className="pt-32 pb-24 relative z-10 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        
        {/* Animated Header Section */}
        <motion.div 
          initial={{ opacity: 0, y: 30 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8, ease: [0.22, 1, 0.36, 1] }}
          className="text-center mb-20 relative"
        >
          <motion.div 
            initial={{ scale: 0.9, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            transition={{ delay: 0.2, duration: 0.8 }}
            className="inline-flex items-center gap-2 px-6 py-2.5 rounded-full bg-white/[0.03] border border-white/10 text-gray-300 text-sm font-medium mb-8 backdrop-blur-md shadow-[0_0_20px_rgba(255,255,255,0.02)]"
          >
            <Sparkles size={16} className="text-primary" />
            <span className="tracking-wide">Words of the Soul</span>
          </motion.div>
          
          <h1 className="text-5xl md:text-7xl lg:text-8xl font-display font-black leading-tight tracking-tighter text-transparent bg-clip-text bg-gradient-to-br from-white via-white to-white/40 mb-8">
            Poetic <span className="text-primary italic font-medium drop-shadow-[0_0_15px_rgba(var(--primary-rgb),0.5)]">Symphony</span>
          </h1>
          
          <p className="text-gray-400 max-w-2xl mx-auto text-lg md:text-xl leading-relaxed font-serif italic">
            "Where silence meets expression, and emotions find their voice." <br className="hidden sm:block"/> 
            A curated sanctuary of Ghazals, Nazms, and unspoken feelings.
          </p>
        </motion.div>

        {/* Search & Filters */}
        <motion.div 
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.3, duration: 0.6 }}
          className="max-w-4xl mx-auto mb-16 space-y-8"
        >
          <div className="relative group">
            <div className="absolute inset-y-0 left-5 flex items-center pointer-events-none">
              <Search className="h-5 w-5 text-gray-500 group-focus-within:text-primary transition-colors" />
            </div>
            <input
              type="text"
              className="w-full bg-white/[0.02] border border-white/10 hover:border-white/20 text-white rounded-3xl pl-14 pr-6 py-5 focus:outline-none focus:border-primary/50 focus:bg-white/[0.04] transition-all duration-300 placeholder:text-gray-600 placeholder:italic backdrop-blur-xl shadow-2xl"
              placeholder="Discover verses, titles, or themes..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
            {/* Elegant glowing border effect on focus */}
            <div className="absolute inset-0 rounded-3xl opacity-0 group-focus-within:opacity-100 transition-opacity duration-500 pointer-events-none border border-primary/20 shadow-[0_0_20px_rgba(var(--primary-rgb),0.1)]" />
          </div>

          {!loading && uniqueTypes.length > 1 && (
            <div className="flex flex-wrap justify-center gap-3">
              {uniqueTypes.map(type => (
                <button
                  key={type}
                  onClick={() => setActiveType(type)}
                  className={`px-6 py-2.5 rounded-full text-sm font-medium transition-all duration-300 ${
                    activeType === type 
                      ? 'bg-primary text-black font-bold shadow-[0_0_20px_rgba(var(--primary-rgb),0.4)] scale-105' 
                      : 'bg-white/5 text-gray-400 hover:bg-white/10 hover:text-white border border-white/5'
                  }`}
                >
                  {type}
                </button>
              ))}
            </div>
          )}
        </motion.div>

        {/* Poetry Masonry/Grid */}
        {loading ? (
          <div className="flex justify-center items-center py-32">
            <div className="relative w-16 h-16">
              <div className="absolute inset-0 border-4 border-primary/20 rounded-full"></div>
              <div className="absolute inset-0 border-4 border-primary rounded-full border-t-transparent animate-spin"></div>
            </div>
          </div>
        ) : filteredPoems.length === 0 ? (
          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            className="text-center py-24 border border-white/5 rounded-[3rem] bg-white/[0.01] backdrop-blur-sm"
          >
            <Feather className="w-12 h-12 text-gray-600 mx-auto mb-6 opacity-50" />
            <h2 className="text-2xl font-bold text-gray-300 mb-3 tracking-tight">No verses found</h2>
            <p className="text-gray-500 italic">Perhaps the words you seek are yet to be written.</p>
          </motion.div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
            <AnimatePresence mode='popLayout'>
              {filteredPoems.map((poem, idx) => (
                <motion.div
                  key={poem.id}
                  layout
                  initial={{ opacity: 0, scale: 0.9, y: 30 }}
                  animate={{ opacity: 1, scale: 1, y: 0 }}
                  exit={{ opacity: 0, scale: 0.9 }}
                  transition={{ duration: 0.5, delay: idx * 0.05 }}
                  className="h-full"
                >
                  <Link
                    href={`/poetry/${poem.slug}`}
                    className="group relative p-8 sm:p-10 rounded-[2.5rem] bg-neutral-900/30 border border-white/5 hover:border-primary/30 transition-all duration-500 flex flex-col h-full overflow-hidden backdrop-blur-md hover:shadow-[0_10px_40px_-10px_rgba(var(--primary-rgb),0.15)] hover:-translate-y-2"
                  >
                    {/* Subtle internal gradient overlay */}
                    <div className="absolute inset-0 bg-gradient-to-br from-white/[0.02] to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
                    
                    {/* Top edge highlight */}
                    <div className="absolute top-0 inset-x-10 h-[1px] bg-gradient-to-r from-transparent via-primary/50 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-700" />

                    {/* Metadata Header */}
                    <div className="flex items-center justify-between mb-8 relative z-10">
                      <span className="text-[10px] font-bold uppercase tracking-widest text-primary bg-primary/10 px-3 py-1 rounded-full border border-primary/20">
                        {poem.type || 'Poetry'}
                      </span>
                      <span className="text-xs text-gray-500 font-medium font-serif italic">
                        {poem.language === 'Urdu' ? 'اردو' : poem.language || 'English'}
                      </span>
                    </div>

                    {/* Title */}
                    <h2 className={`font-bold text-white mb-6 group-hover:text-primary transition-colors duration-300 leading-tight relative z-10 ${poem.language === 'Urdu' ? 'font-urdu text-3xl text-right leading-relaxed' : 'text-2xl'}`}>
                      {poem.title}
                    </h2>

                    {/* Content Snippet */}
                    <div className="relative mb-10 flex-grow z-10">
                      <Feather className="absolute -left-3 -top-3 w-6 h-6 text-white/5 -rotate-12 transition-transform group-hover:rotate-12 group-hover:scale-110 duration-500" />
                      <p className={`text-gray-400 italic leading-relaxed line-clamp-4 ${poem.language === 'Urdu' ? 'font-urdu text-right text-xl leading-[2.5]' : 'font-serif'}`}>
                        {poem.content ? poem.content.split('\n')[0] + (poem.content.split('\n').length > 1 ? '\n' + poem.content.split('\n')[1] : '') : ''}
                      </p>
                    </div>

                    {/* Footer / Interaction */}
                    <div className="mt-auto pt-6 border-t border-white/5 flex items-center justify-between relative z-10">
                      <span className="text-xs text-gray-500 uppercase tracking-wider font-semibold">
                         {poem.publishedAt?.toDate ? new Date(poem.publishedAt.toDate()).toLocaleDateString('en-US', { day: 'numeric', month: 'short', year: 'numeric' }) : ''}
                      </span>
                      
                      <div className="flex items-center gap-1">
                        <span className="text-xs font-bold text-transparent bg-clip-text bg-gradient-to-r from-primary to-primary/70 opacity-0 group-hover:opacity-100 transition-all duration-300 -translate-x-2 group-hover:translate-x-0 mr-2">
                          Read More
                        </span>
                        <div className="w-8 h-8 rounded-full bg-white/5 flex items-center justify-center group-hover:bg-primary/10 transition-colors">
                          <ArrowUpRight size={16} className="text-gray-400 group-hover:text-primary transition-colors" />
                        </div>
                      </div>
                    </div>
                  </Link>
                </motion.div>
              ))}
            </AnimatePresence>
          </div>
        )}
      </div>
    </main>
  );
}
